<script setup lang="ts">
import {ref,shallowRef,computed,reactive,watch,onScopeDispose,useId} from 'vue'
import {Refresh,FullScreen,Download,Plus} from '@element-plus/icons-vue'
import {ApiError,IdentityChanged,identityEpoch,assertIdentity,onIdentityChange,errorMessage} from '@/core/http'
import {projectId,can} from '@/core/session'
import {formatTime} from '@/core/time'
import {devicesApi} from './api'
import {propertySeriesFrame} from './property-series-api'
import {seriesDecimal,instantKey,type PropertySeries,type SeriesPoint,type SeriesQuery} from './property-series-json'
import EastEightDateTimeInput from './HistoryRemovalDateTimeInput.vue'
import {useEastEightRange} from './device-civil-time'
import {seriesSteps,seriesAggregates,seriesPresets,presetRange,minimumSeriesStep,type SeriesStep,type SeriesAggregate} from './property-series-options'
import {plotSeries,seriesStatistics,compareDecimals,seriesValueY,linePath,type SeriesAxis} from './property-series-presentation'
import {downloadSeries} from './property-series-export'
export type CurveProperty={key:string;name:string;dataType:string}
const props=defineProps<{deviceId:string;propertyKey:string;modelVersionId?:string;properties?:readonly CurveProperty[]}>()
const emit=defineEmits<{close:[];unavailable:[cause:unknown]}>()
const range=ref<[Date,Date]>(presetRange('last_1h')!),preset=ref('last_1h'),granularity=ref<SeriesStep>('RAW'),aggregation=ref<SeriesAggregate>('AVG')
const comparisons=ref<string[]>([]),comparisonDraft=ref<string[]>([]),comparisonOpen=ref(false),mode=ref<'line'|'bar'|'scatter'>('line'),fullscreen=ref(false),autoUpdate=ref(false),showPoints=ref(true),showMinimum=ref(true),showMaximum=ref(true),showAverage=ref(true),stepLine=ref(false)
const axisDraft=reactive<Record<string,{automaticMinimum:boolean;automaticMaximum:boolean;minimum:string;maximum:string}>>({}),axes=shallowRef<Record<string,SeriesAxis>>({}),axisError=ref('')
const frame=shallowRef<readonly PropertySeries[]>(),loading=ref(false),error=shallowRef<unknown>(),hover=shallowRef<{property:string;point:SeriesPoint}>(),exportDialog=ref(false),exportFormat=ref<'xlsx'|'csv'>('xlsx')
const allowed=computed(()=>can('device:read')),keys=computed(()=>[props.propertyKey,...comparisons.value]),choices=computed(()=>[...(props.properties||[]).filter(item=>item.dataType==='NUMBER'&&item.key!==props.propertyKey)])
const names=computed(()=>Object.fromEntries((props.properties||[]).map(item=>[item.key,item.name==='—'?item.key:item.name])))
const colors=['#5470c6','#91cc75','#fac858','#ee6666','#73c0de']
const color=(key:string)=>colors[keys.value.indexOf(key)%colors.length]!
const sourceName=(source:SeriesPoint['sourceKind'])=>({DEVICE_REPORT:'设备上报',PLATFORM_DOWNLINK:'属性下发',PLATFORM_CLOUD_UPDATE:'云端更新'}[source!])
const clipId='curve-plot-'+useId().replace(/[^A-Za-z0-9_-]/g,'')
const {draft:dateDraft,dirty:dateDirty,edit:editDraft,parse:parseDates,reset:resetDateDrafts}=useEastEightRange(range)
const time=formatTime
const timeTicks=computed(()=>Array.from({length:5},(_,index)=>({x:24+index*148,text:formatTime(new Date(range.value[0].getTime()+(range.value[1].getTime()-range.value[0].getTime())*index/4).toISOString()).slice(5,16)})))
const label=(key:string)=>names.value[key]||key
const plot=computed(()=>plotSeries(frame.value||[],axes.value,[range.value[0].toISOString(),range.value[1].toISOString()]))
const hoveredPosition=computed(()=>{if(!hover.value)return;for(const line of plot.value){if(line.property!==hover.value.property)continue;const hit=line.points.find(item=>item.point===hover.value!.point);if(hit)return {left:`${Math.max(5,Math.min(75,hit.x/640*100))}%`,top:`${Math.max(4,Math.min(75,hit.y/220*100))}%`}}})
const statistics=computed(()=>plot.value.map(line=>{const points=line.points.map(item=>item.point),stats=seriesStatistics(points)!,sorted=[...points].sort((a,b)=>compareDecimals(a.value,b.value)),middle=Math.floor(sorted.length/2),medianStats=sorted.length%2?undefined:seriesStatistics([sorted[middle-1]!,sorted[middle]!]),median=sorted.length%2?sorted[middle]!.value.lexical:medianStats!.average
 return{...line,...stats,median,medianApproximate:medianStats?.approximate||false,count:points.length,minimumPoint:line.points.find(item=>item.point.value.lexical===stats.minimum),maximumPoint:line.points.find(item=>item.point.value.lexical===stats.maximum),averageY:seriesValueY(frame.value!.find(result=>result.propertyKey===line.property)!.points,seriesDecimal(stats.average),axes.value[line.property])}}))
const tableRows=computed(()=>(frame.value?.flatMap(result=>result.points.map(point=>({property:result.propertyKey!,point})))||[]).sort((a,b)=>instantKey(a.point.ts!).localeCompare(instantKey(b.point.ts!))))
type CurveRow={property:string;point:SeriesPoint}
const sortTime=(a:CurveRow,b:CurveRow)=>instantKey(a.point.ts!).localeCompare(instantKey(b.point.ts!))
const sortProperty=(key:string)=>(a:CurveRow,b:CurveRow)=>a.property===key&&b.property===key?compareDecimals(a.point.value,b.point.value):a.property===key?-1:b.property===key?1:0
const axisRanges=computed(()=>frame.value?.map(result=>{const stats=seriesStatistics(result.points),axis=axes.value[result.propertyKey!];return{key:result.propertyKey!,minimum:axis?.minimum?.lexical||stats?.minimum||'—',maximum:axis?.maximum?.lexical||stats?.maximum||'—'}})||[])
const zero=seriesDecimal('0')
function barBase(key:string){const result=frame.value!.find(item=>item.propertyKey===key)!,value=seriesValueY(result.points,zero,axes.value[key]);if(value!==undefined)return value;const stats=seriesStatistics(result.points);return stats&&compareDecimals(seriesDecimal(stats.maximum),zero)<0?24:196}
const canExport=computed(()=>allowed.value&&!dateDirty.value&&!loading.value&&!error.value&&!!tableRows.value.length)
let sequence=0,controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,disposed=false
function cancel(){sequence++;controller?.abort();controller=undefined;clearTimeout(timer);timer=undefined;frame.value=undefined;hover.value=undefined;error.value=undefined;loading.value=false;exportDialog.value=false}
function close(){cancel();comparisonOpen.value=false;comparisonDraft.value=[];autoUpdate.value=false;emit('close')}
function deny(cause:unknown){cancel();comparisonOpen.value=false;comparisonDraft.value=[];comparisons.value=[];autoUpdate.value=false;Object.keys(axisDraft).forEach(key=>delete axisDraft[key]);axes.value={};emit('unavailable',cause);emit('close')}
function schedule(){clearTimeout(timer);if(!disposed&&autoUpdate.value&&!dateDirty.value&&keys.value.length===1&&allowed.value&&document.visibilityState!=='hidden')timer=setTimeout(()=>void load(true),15000)}
async function load(sliding=false){
 if(disposed)return
 cancel();if(!allowed.value){deny(new ApiError('当前账号已无属性读取权限',403));return}
 if(sliding&&preset.value!=='custom')range.value=presetRange(preset.value)!
 const project=projectId.value,device=props.deviceId,model=props.modelVersionId,properties=[...keys.value],requested=granularity.value,aggregate=aggregation.value
 const request=++sequence,identity=identityEpoch()
 controller=new AbortController();const signal=controller.signal;loading.value=true
 try{
  if(dateDirty.value)range.value=parseDates()
  const from=range.value?.[0]?.toISOString(),to=range.value?.[1]?.toISOString()
  if(!from||!to||!project)throw new Error('请选择有效时间范围和项目')
  let expected=model
  if(!expected){const binding=await devicesApi.binding(project,device,signal);if(binding.deviceId!==device||!binding.version?.id)throw new Error('设备当前模型不可用，请刷新设备信息');expected=binding.version.id}
  const queries:SeriesQuery[]=properties.map(property=>({project,device,model:expected!,property,from,to,granularity:requested,aggregation:aggregate}))
  const result=await propertySeriesFrame(queries,signal);assertIdentity(identity)
  if(request!==sequence||signal.aborted||!allowed.value)return
  frame.value=result
 }catch(cause){if(request===sequence&&!signal.aborted&&!(cause instanceof IdentityChanged)){
  if(cause instanceof ApiError&&[401,403,404].includes(cause.status)){deny(cause);return}
  frame.value=undefined;hover.value=undefined;error.value=cause
 }}finally{if(request===sequence){loading.value=false;schedule()}}
}
function search(){try{if(dateDirty.value)range.value=parseDates();const [from,to]=range.value;if(Number.isFinite(from.getTime())&&Number.isFinite(to.getTime())){const minimum=minimumSeriesStep(from.toISOString(),to.toISOString());if(seriesSteps.findIndex(item=>item.value===granularity.value)<seriesSteps.findIndex(item=>item.value===minimum))granularity.value=minimum}void load()}catch(cause){cancel();error.value=cause}}
function changePreset(){const next=presetRange(preset.value);if(next){range.value=next;search()}}
function editDate(index:0|1,value:string|undefined){editDraft(index,value);preset.value='custom';cancel()}
function changeDates(){preset.value='custom';search()}
function openComparison(){comparisonDraft.value=[...comparisons.value];comparisonOpen.value=true}
function confirmComparison(){comparisons.value=[...comparisonDraft.value];comparisonOpen.value=false;changeComparisons()}
function cancelComparison(){comparisonOpen.value=false;comparisonDraft.value=[...comparisons.value]}
function changeComparisons(){if(comparisons.value.length>4)comparisons.value=comparisons.value.slice(0,4);if(comparisons.value.length)autoUpdate.value=false;axes.value={};axisError.value='';Object.keys(axisDraft).forEach(key=>delete axisDraft[key]);search()}
function draft(key:string){return axisDraft[key]||(axisDraft[key]={automaticMinimum:true,automaticMaximum:true,minimum:'',maximum:''})}
function applyAxis(key:string){hover.value=undefined;axisError.value='';try{const value=draft(key),next={...axes.value},minimum=!value.automaticMinimum&&value.minimum.trim()?seriesDecimal(value.minimum.trim()):undefined,maximum=!value.automaticMaximum&&value.maximum.trim()?seriesDecimal(value.maximum.trim()):undefined;if(minimum&&maximum&&compareDecimals(minimum,maximum)>=0)throw new Error('纵轴最小值必须小于最大值');if(minimum||maximum)next[key]={minimum,maximum};else delete next[key];plotSeries(frame.value||[],next);axes.value=next}catch(cause){axisError.value=errorMessage(cause)}}
function toggleAxis(key:string){applyAxis(key)}
function saveExport(){if(!canExport.value)return;downloadSeries(frame.value!,names.value,exportFormat.value);exportDialog.value=false}
function visible(){if(document.visibilityState==='hidden'){clearTimeout(timer);timer=undefined}else schedule()}
const disposeIdentity=onIdentityChange(()=>deny(new IdentityChanged()))
watch(()=>[projectId.value,props.deviceId,props.propertyKey],()=>{resetDateDrafts();comparisonOpen.value=false;comparisonDraft.value=[];comparisons.value=[];axes.value={};Object.keys(axisDraft).forEach(key=>delete axisDraft[key]);void load()},{immediate:true})
watch(()=>props.modelVersionId,(next,previous)=>{if(next!==previous)close()})
watch(allowed,value=>{if(!value)deny(new ApiError('当前账号已无属性读取权限',403))},{flush:'sync'})
watch(autoUpdate,schedule)
document.addEventListener('visibilitychange',visible)
onScopeDispose(()=>{disposed=true;cancel();disposeIdentity();document.removeEventListener('visibilitychange',visible)})
</script>
<template>
<el-dialog :model-value="true" title="属性时序图表" width="960px" :fullscreen="fullscreen" class="property-curve-dialog" @close="close">
 <div class="curve-toolbar">
  <form class="curve-query" @submit.prevent="search">
   <el-select v-model="preset" aria-label="时间预设" class="curve-preset" @change="changePreset"><el-option v-for="[key,text] in seriesPresets" :key="key" :value="key" :label="text"/></el-select>
   <div class="curve-date-range" aria-label="东八区时间范围"><EastEightDateTimeInput :model-value="dateDraft[0]" size="small" :clearable="false" placeholder="开始时间" @update:model-value="editDate(0,$event)" @change="changeDates"/><span>-</span><EastEightDateTimeInput :model-value="dateDraft[1]" size="small" :clearable="false" placeholder="结束时间" @update:model-value="editDate(1,$event)" @change="changeDates"/></div>
   <el-select v-model="granularity" aria-label="汇总窗口" class="curve-window" @change="search"><el-option v-for="item in seriesSteps" :key="item.value" :value="item.value" :label="item.label" :disabled="range?.length===2&&(range[1].getTime()-range[0].getTime())/1000>item.maximum&&item.value!=='ONE_MONTH'"/></el-select>
   <el-tooltip v-if="granularity!=='RAW'" :content="aggregation==='SPREAD'?'首尾差值按最大值减最小值计算':'对实际可读窗口内的原始样本汇总，边缘时间桶可能不完整'"><el-select v-model="aggregation" aria-label="汇总函数" class="curve-function" @change="search"><el-option v-for="item in seriesAggregates" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-tooltip>
  </form>
  <div class="curve-actions"><el-button-group><el-button size="small" :type="mode==='line'?'primary':''" aria-label="折线图" @click="mode='line'"><span class="reference-icon curve-mode-icon" aria-hidden="true">󰄪</span></el-button><el-button size="small" :type="mode==='bar'?'primary':''" aria-label="柱状图" @click="mode='bar'"><span class="reference-icon curve-mode-icon" aria-hidden="true">󰄨</span></el-button><el-button size="small" :type="mode==='scatter'?'primary':''" aria-label="散点图" @click="mode='scatter'"><span class="reference-icon curve-mode-icon" aria-hidden="true">󰺒</span></el-button></el-button-group><el-button size="small" :icon="Refresh" :loading="loading" aria-label="刷新曲线" @click="load(true)"/><el-tooltip content="切换全屏"><el-button size="small" :icon="FullScreen" :type="fullscreen?'primary':''" aria-label="切换全屏" @click="fullscreen=!fullscreen"/></el-tooltip></div>
 </div>
 <div class="curve-properties"><el-popover :teleported="false" :width="280" trigger="click" placement="bottom-start"><template #reference><button type="button" class="curve-property-tag" aria-label="纵轴设置">{{label(propertyKey)}} <small v-if="label(propertyKey)!==propertyKey">({{propertyKey}})</small> ⚙</button></template><div class="curve-axis"><strong>{{label(propertyKey)}}</strong><div v-for="key in keys" :key="key" class="curve-axis-row"><div class="curve-axis-range">数据范围: {{axisRanges.find(axis=>axis.key===key)?.minimum}} ~ {{axisRanges.find(axis=>axis.key===key)?.maximum}}</div><div class="curve-axis-control"><span>Y 轴上限</span><span>自动</span><el-switch v-model="draft(key).automaticMaximum" :aria-label="`${key}纵轴上限自动`" @change="toggleAxis(key)"/></div><el-input v-if="!draft(key).automaticMaximum" v-model="draft(key).maximum" :aria-label="`${key}纵轴最大值`" placeholder="输入上限值" @change="applyAxis(key)"/><div class="curve-axis-control"><span>Y 轴下限</span><span>自动</span><el-switch v-model="draft(key).automaticMinimum" :aria-label="`${key}纵轴下限自动`" @change="toggleAxis(key)"/></div><el-input v-if="!draft(key).automaticMinimum" v-model="draft(key).minimum" :aria-label="`${key}纵轴最小值`" placeholder="输入下限值" @change="applyAxis(key)"/></div><p v-if="axisError" role="alert">{{axisError}}</p></div></el-popover><el-popover :visible="comparisonOpen" :teleported="false" placement="bottom-start" :width="240" trigger="click"><template #reference><el-button size="small" type="primary" plain @click="openComparison">＋ 对比</el-button></template><el-select v-if="choices.length" v-model="comparisonDraft" :teleported="false" multiple :multiple-limit="4" collapse-tags collapse-tags-tooltip placeholder="选择对比属性（最多4个）" aria-label="对比属性" size="small" style="width:100%"><el-option v-for="item in choices" :key="item.key" :value="item.key" :label="`${item.name} (${item.key})`"/></el-select><p v-else class="curve-comparison-empty">暂无可对比属性</p><div class="curve-comparison-actions"><el-button type="primary" size="small" @click="confirmComparison">确定</el-button><el-button size="small" @click="cancelComparison">取消</el-button></div></el-popover><span v-for="key in comparisons" :key="key"><i :style="{background:color(key)}"/>{{label(key)}}</span><el-tooltip content="属性图表加入看板尚未接入"><span class="curve-dashboard-action"><el-button size="small" type="primary" plain :icon="Plus" disabled>加入看板</el-button></span></el-tooltip></div>

 <div v-if="loading" class="curve-status" role="status"><el-skeleton :rows="3" animated/></div>
 <div v-else-if="error" class="curve-status" role="alert"><p>{{errorMessage(error)}}</p><el-button size="small" @click="load()">重新读取</el-button></div>
 <template v-else>
 <div class="curve-legend"><span v-for="key in keys" :key="key"><i :style="{background:color(key)}"/>{{label(key)}}</span></div><div class="curve-chart"><svg viewBox="0 0 640 220" role="img" aria-label="属性历史曲线"><defs><clipPath :id="clipId"><rect x="24" y="16" width="592" height="184"/></clipPath></defs><path d="M24 16 V196 H616" fill="none" stroke="#dcdfe6"/><path d="M24 24 H616 M24 67 H616 M24 110 H616 M24 153 H616" stroke="#eee" fill="none"/><g v-if="axisRanges.length===1&&axisRanges[0]!.minimum!=='—'&&axisRanges[0]!.minimum!==axisRanges[0]!.maximum" fill="#909399" font-size="7" text-anchor="end"><text x="20" y="27">{{axisRanges[0]!.maximum}}</text><text x="20" y="196">{{axisRanges[0]!.minimum}}</text></g><text v-for="tick in timeTicks" :key="tick.x" :x="tick.x" y="214" :text-anchor="tick.x===24?'start':tick.x===616?'end':'middle'" fill="#909399" font-size="7">{{tick.text}}</text>
 <g :clip-path="`url(#${clipId})`"><g v-for="line in plot" :key="line.id" :data-series="line.id">
 <template v-if="mode==='line'"><path v-for="(segment,index) in line.segments" :key="index" :d="linePath(segment,stepLine)" fill="none" :stroke="color(line.property)" :stroke-dasharray="line.source==='DEVICE_REPORT'?undefined:line.source==='PLATFORM_DOWNLINK'?'5 3':'2 3'" stroke-width="2"/></template>
 <template v-for="(point,index) in line.points" :key="index"><rect v-if="mode==='bar'&&point.visible" :x="point.x-3" :y="Math.min(point.y,barBase(line.property))" width="6" :height="Math.max(1,Math.abs(barBase(line.property)-point.y))" :fill="color(line.property)" opacity="0.7"><title>{{time(point.point.ts)}} · {{label(line.property)}} · {{sourceName(line.source)}} · {{point.point.value.lexical}}</title></rect><circle v-if="point.visible&&(showPoints||mode==='scatter')" :cx="point.x" :cy="point.y" :r="mode==='scatter'?4:3" :fill="color(line.property)" tabindex="0" @mouseenter="hover={property:line.property,point:point.point}" @mouseleave="hover=undefined" @focus="hover={property:line.property,point:point.point}" @blur="hover=undefined"><title>{{time(point.point.ts)}} · {{label(line.property)}} · {{sourceName(line.source)}} · {{point.point.value.lexical}}</title></circle></template>
 </g><g v-for="item in statistics" :key="item.id+'stats'"><path v-if="showAverage&&item.averageY!==undefined" :d="`M24 ${item.averageY} H616`" :stroke="color(item.property)" stroke-dasharray="3 4" opacity="0.6"/><text v-if="showMaximum&&item.maximumPoint?.visible" :x="Math.max(50,Math.min(590,item.maximumPoint.x))" :y="Math.max(22,item.maximumPoint.y-7)" text-anchor="middle" :fill="color(item.property)" font-size="9">{{item.maximum}}</text><text v-if="showMinimum&&item.minimumPoint?.visible" :x="Math.max(50,Math.min(590,item.minimumPoint.x))" :y="Math.min(199,item.minimumPoint.y+13)" text-anchor="middle" :fill="color(item.property)" font-size="9">{{item.minimum}}</text></g></g>
 <text v-if="!tableRows.length" class="curve-empty-label" x="320" y="110" text-anchor="middle" fill="#909399" font-size="13">暂无数据</text>
 </svg><div v-if="hover&&hoveredPosition" class="curve-point-tooltip curve-hover" :style="hoveredPosition" role="status"><time>{{time(hover.point.ts)}}</time><div>{{label(hover.property)}}：{{hover.point.value.lexical}}</div><small>{{sourceName(hover.point.sourceKind)}} · {{hover.point.sampleCount}} 个样本 · {{hover.point.modelVersion}}</small></div></div>
 </template>
 <div class="curve-settings"><el-tooltip :content="comparisons.length?'多属性对比时不能自动更新':'单属性每15秒重新读取；隐藏页面暂停'"><el-checkbox v-model="autoUpdate" :disabled="!!comparisons.length">自动更新</el-checkbox></el-tooltip><div><el-checkbox v-model="showPoints">标注数据点</el-checkbox><el-checkbox v-model="showMaximum">标注最大值</el-checkbox><el-checkbox v-model="showMinimum">标注最小值</el-checkbox><el-checkbox v-model="showAverage">标注均值线</el-checkbox><el-checkbox v-if="mode==='line'" v-model="stepLine">阶梯图</el-checkbox></div></div>

 <div class="curve-bottom-actions"><el-tooltip content="属性数据加入看板尚未接入"><span><el-button size="small" type="primary" plain :icon="Plus" disabled>加入看板</el-button></span></el-tooltip><el-tooltip content="导出本次完整读取的图中点，包含来源、历史模型和精度；Excel数值按文本保存"><el-button size="small" :icon="Download" :disabled="!canExport" @click="exportDialog=true">导出</el-button></el-tooltip></div>
 <el-table :data="tableRows" max-height="300" class="curve-table"><el-table-column label="时间" min-width="170" sortable :sort-method="sortTime"><template #default="{row}"><el-tooltip :content="time(row.point.ts)"><time :datetime="row.point.ts">{{time(row.point.ts)}}</time></el-tooltip></template></el-table-column><el-table-column v-for="key in keys" :key="key" :label="label(key)" min-width="150" align="right" sortable :sort-method="sortProperty(key)"><template #default="{row}">{{row.property===key?row.point.value.lexical:'—'}}</template></el-table-column></el-table>
 <details v-if="statistics.length" v-show="false" class="curve-statistics-details"><summary>统计信息</summary><div class="curve-statistics"><article v-for="item in statistics" :key="item.id"><strong :style="{color:color(item.property)}">{{label(item.property)}} · {{sourceName(item.source)}} · {{item.model}}</strong><dl><div v-for="[title,value] in [['最小值',item.minimum],['最大值',item.maximum],['平均值',(item.approximate?'≈':'')+item.average],['中位数',(item.medianApproximate?'≈':'')+item.median],['点数',item.count]]" :key="title"><dt>{{title}}</dt><dd :title="String(value)">{{value}}</dd></div></dl></article></div></details>
 <details v-show="false" class="curve-extra-info"><summary>图表读取与统计信息</summary><div v-if="tableRows.length" class="curve-time-labels"><time :title="time(tableRows[0]!.point.ts)">{{time(tableRows[0]!.point.ts!)}}</time><time :title="time(tableRows[tableRows.length-1]!.point.ts)">{{time(tableRows[tableRows.length-1]!.point.ts!)}}</time></div>
 <div class="curve-axis-labels"><span v-for="axis in axisRanges" :key="axis.key" :style="{color:color(axis.key)}" :title="`${axis.minimum} — ${axis.maximum}`">{{label(axis.key)}} · {{axes[axis.key]?'手动':'自动'}}纵轴 {{axis.minimum}} — {{axis.maximum}}</span></div>

 <div v-if="frame?.length" class="curve-receipt">实际粒度 {{seriesSteps.find(item=>item.value===frame![0]!.actualGranularity)?.label}}<span v-if="frame[0]!.actualGranularity!=='RAW'"> · {{seriesAggregates.find(item=>item.value===frame![0]!.aggregation)?.label}} · 边缘时间桶可能不完整</span><el-tooltip content="设备上报按设备采集时间；属性下发和云端更新按平台受理时间，不表示设备已收到。旧上报数值精度受Double来源限制，详情及导出保留数值词法。"><span class="curve-help">来源与精度说明</span></el-tooltip></div>
 <details v-if="frame?.length" class="curve-windows"><summary>实际读取范围</summary><div v-for="result in frame" :key="result.propertyKey"><strong>{{label(result.propertyKey!)}}</strong><p>设备上报：{{time(result.reportedWindow!.from!)}} — {{time(result.reportedWindow!.to!)}}</p><p>平台受理：{{time(result.platformWindow!.from!)}} — {{time(result.platformWindow!.to!)}}</p></div></details></details>
